# owner: platform
"""Tests for the substitute teacher contact sheet."""

import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows

def make(last, first, section, email):
    return Student("0", last, first, section, email)

class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name_and_aligned(self):
        students = [
            make("Varrow", "Ines", "A", "ines@x.edu"),
            make("Thistle", "Bram", "B", "bram@x.edu")
        ]
        self.assertEqual(
            contact_rows(students),
            [
                "Thistle, Bram        B        bram@x.edu",
                "Varrow, Ines         A        ines@x.edu"
            ]
        )

    def test_missing_email_names_the_student(self):
        students = [make("Quillon", "Sefa", "A", None)]
        with self.assertRaisesRegex(
            ValueError, "Quillon, Sefa"
        ):
            contact_rows(students)

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
